/* Bearer auth gate. */
const req = $input.first().json;
const headers = req.headers || {};
const expectedKey = $env.CHAT_API_KEY;
const provided = String(headers.authorization || '').replace(new RegExp('^' + 'Bea' + 'rer\\s+', 'i'), '');
if (!expectedKey || provided !== expectedKey) {
  return [{ json: { __error: true, status: 401, body: { error: { message: 'Invalid API key.', type: 'authentication_error', code: 'invalid_api_key' } } } }];
}
return [{ json: { ok: true } }];

/* Log a streamed turn: 2 message rows + 1 execution row (stats parity). */
const body = ($('Webhook Log').first().json.body) || {};
const api = (method, path, qs, payload) => this.helpers.httpRequest({ method, url: 'http://localhost:5678/api/v1' + path, headers: { 'X-N8N-API-KEY': $env.N8N_API_KEY, 'Content-Type': 'application/json' }, qs, body: payload });
const tables = (await api('GET', '/data-tables', { limit: 100 })).data || [];
const msgsId = (tables.find((t) => t.name === 'chat_messages') || {}).id;
const execId = (tables.find((t) => t.name === 'chat_executions') || {}).id;
if (!msgsId || !execId) return [{ json: { ok: false, error: 'chat tables missing (run deploy.mjs)' } }];
const session_id = String(body.session_id || 'lobehub');
const model = String(body.model || '');
const client = String(body.client || 'stream');
const usage = body.usage || {};
const rows = [
  { session_id, role: 'user', content: String(body.user_text || '').slice(0, 20000), model, client, key_name: '', cost_usd: 0 },
  { session_id, role: 'assistant', content: String(body.assistant_text || '').slice(0, 20000), model, client, key_name: '', cost_usd: 0 },
];
await api('POST', '/data-tables/' + msgsId + '/rows', null, { data: rows });
await api('POST', '/data-tables/' + execId + '/rows', null, { data: [{
  execution_id: 'stream-' + Date.now(), session_id, model, client, key_name: '', cost_usd: 0,
  status: 'success', error_code: '', error_message: '',
  latency_ms: Number(body.latency_ms) || 0,
  prompt_tokens: Number(usage.prompt_tokens) || 0,
  completion_tokens: Number(usage.completion_tokens) || 0,
  total_tokens: Number(usage.total_tokens) || 0,
}] });
return [{ json: { ok: true, logged: rows.length + 1, session_id } }];
